package com.bank.payroll.model;

import java.math.BigDecimal;

// Normal (non-static) domain class — one job: hold employee data.
public class Employee {
    private final String name;
    private final String department;
    private final String gender;
    private final int age;
    private final String email;
    private final BigDecimal salary;

    public Employee(String name, String department, String gender,
                    int age, String email, BigDecimal salary) {
        this.name = name;
        this.department = department;
        this.gender = gender;
        this.age = age;
        this.email = email;
        this.salary = salary;
    }

    public String getName()        { return name; }
    public String getDepartment()  { return department; }
    public String getGender()      { return gender; }
    public int getAge()            { return age; }
    public String getEmail()       { return email; }
    public BigDecimal getSalary()  { return salary; }

    @Override public String toString() {
        return name + " (" + department + ", Rs." + salary + ")";
    }
}
