package com.bank.payroll.service;

import com.bank.payroll.model.Employee;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class PayrollService {
    private static final Logger log = Logger.getLogger(PayrollService.class.getName());
    private static final BigDecimal THRESHOLD = new BigDecimal("50000");

    // Keep only employees whose salary is strictly greater than 50,000.
    public List<Employee> highEarners(List<Employee> employees) {
        log.info(() -> "Filtering " + employees.size() + " employees for salary > 50000");
        return employees.stream()
                .filter(e -> e.getSalary().compareTo(THRESHOLD) > 0) // BigDecimal compare, never double
                .collect(Collectors.toList());
    }
}
